insert into public.chunks (id, item_id, page_no, chunk_index, content) values ('00000000-0000-4000-a000-000000011341', '00000000-0000-4000-a000-000000000134', 1, 0, 'Illustration caption: a Himalayan glacier snout below high peaks. Sample illustration, not a photograph.') on conflict do nothing;
